const m=$json.message||{};const text=(m.caption||m.text||'').trim();
const mt=text.match(/#(studio|adshot|bg|video|film|voice|captions|ads|hooks|seo|email)\s+(\w+)\s*(.*)/is);
if(!mt)return [];
return [{ json: { cmd:mt[1].toLowerCase(), client:mt[2].toLowerCase(), arg:mt[3]||'', chat:m.chat.id, hasPhoto:!!m.photo }, binary:items[0].binary }];

const p=$('T2 parse cmd+client').item.json;
const brand=items.map(i=>i.json).find(r=>(r.Client||'').toLowerCase()===p.client)||{Client:p.client,Colors:'',Tone:'premium warm',VoiceID:$env.ELEVENLABS_VOICE_ID,Watermark:p.client};
return [{ json: { ...p, brand }, binary: $('T2 parse cmd+client').item.binary }];

const j=$json;const bin=items[0].binary?.data;if(!bin)throw new Error('Send a PHOTO with the command');
const prompts={studio:`professional luxury studio product photograph, ${j.brand.Colors?('brand palette '+j.brand.Colors+', '):''}soft key light, crisp focus, no text/people`,adshot:`high-converting ad creative shot, bold ${j.brand.Colors||'brand'} background, product hero, space for headline`,bg:`replace background with: ${j.arg}. keep product identical, realistic light match`};
return [{ json: { body: { contents:[{parts:[{inlineData:{mimeType:bin.mimeType||'image/jpeg',data:bin.data}},{text:'Re-render: '+prompts[j.cmd]}]}], generationConfig:{responseModalities:['TEXT','IMAGE']} } }, binary: items[0].binary }];
